CREATE TABLE IF NOT EXISTS external_identities (
  id TEXT PRIMARY KEY,
  source_key TEXT UNIQUE,
  system TEXT,
  external_id TEXT,
  subject_resource TEXT,
  subject_id TEXT,
  subject_owner TEXT CHECK(subject_owner IN ('host', 'package')),
  subject_owner_package TEXT,
  subject_label TEXT,
  status TEXT CHECK(status IN ('active', 'superseded')),
  first_observed_run_id TEXT,
  last_observed_run_id TEXT,
  first_observed_at TEXT,
  last_observed_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
) STRICT;
CREATE INDEX IF NOT EXISTS external_identities_system ON external_identities(system);
CREATE INDEX IF NOT EXISTS external_identities_external_id ON external_identities(external_id);
CREATE INDEX IF NOT EXISTS external_identities_subject_resource ON external_identities(subject_resource);
CREATE INDEX IF NOT EXISTS external_identities_subject_id ON external_identities(subject_id);
CREATE INDEX IF NOT EXISTS external_identities_status ON external_identities(status);
